cat > src/inset_panel.rs <<'EOF'
//! A floating panel over the whole main window, inset from its edges, with the
//! window dimmed behind it. It is modal: clicking the dimmed window closes it,
//! nothing beneath takes the mouse, and <Tab> cycles focus within it. Keeping
//! focus from going beneath otherwise is up to whatever shows it.
//!
//! It animates in and out: the dimming fades in behind it, and the panel fades
//! in as it settles into place from a little lower, as though tipping up
//! towards the viewer; closing plays the same backwards, the panel no longer
//! taking the mouse or focus while it goes.

use std::time::Duration;

use gpui_kit::component::{ActiveTheme as _, FocusTrapElement as _};
use gpui_kit::*;

/// How far the panel is inset from each edge of the window.
pub const INSET: Pixels = px(32.);

/// How dark the window behind an open panel is.
const DIM: f32 = 0.4;

/// How far below its place the panel starts, and settles from.
const DROP: Pixels = px(28.);

/// How the panel moves in and out.
const SPRING: SpringConfig = SpringConfig::new(380., 38., 1.);

/// How long closing takes to finish, after which the panel is gone.
pub const CLOSE_TIME: Duration = Duration::from_millis(260);

/// How far in a panel is, from 0 for gone to 1 for fully open.
fn motion(opening: bool) -> SpringAnimation<f32> {
    if opening {
        SpringAnimation::new(SPRING).to(1.).from(0.)
    } else {
        SpringAnimation::new(SPRING).to(0.).from(1.)
    }
}

/// The dimmed window behind a panel, and the panel at `progress` of the way
/// in, applied to `backdrop` and `panel`.
fn frame(progress: f32, panel: Div) -> Div {
    let progress = progress.clamp(0., 1.);
    panel
        .opacity(progress)
        .top(INSET + DROP * (1. - progress))
        .bottom(INSET - DROP * (1. - progress))
}

/// `content` in a panel whose elements are named `{name}-panel` and
/// `{name}-backdrop`, tracking `focus` and trapping <Tab> within it, and
/// calling `close` when the dimmed window around it is clicked. `opened`
/// counts the times a panel has opened, so each opening animates afresh.
pub fn inset_panel(
    name: &str,
    focus: &FocusHandle,
    content: impl IntoElement,
    close: impl Fn(&ClickEvent, &mut Window, &mut App) + 'static,
    opened: usize,
    cx: &App,
) -> AnyElement {
    let theme = cx.theme();
    let panel = div()
        .absolute()
        .left(INSET)
        .right(INSET)
        .top(INSET)
        .bottom(INSET)
        .overflow_hidden()
        .rounded_lg()
        .border_1()
        .border_color(theme.border)
        .bg(theme.background)
        .shadow_2xl()
        // Focus is tracked and trapped within what the panel holds.
        .child(
            div()
                .size_full()
                .track_focus(focus)
                .child(content)
                .focus_trap(SharedString::from(format!("{name}-trap")), focus),
        )
        .with_spring(("inset-panel-in", opened), motion(true), |panel, progress| {
            frame(progress, panel)
        });
    let panel = div()
        .id(SharedString::from(format!("{name}-panel")))
        .absolute()
        .inset_0()
        // Clicks inside stay inside, rather than reaching the backdrop.
        .child(div().absolute().inset(INSET).occlude())
        .child(panel);
    // Lets UI tests find the panel; inert in normal builds.
    let panel = gpui_kit::TestSupportExt::test_support(panel);
    let dim = div()
        .absolute()
        .inset_0()
        .with_spring(("inset-panel-dim-in", opened), motion(true), |dim, progress| {
            dim.bg(black().opacity(DIM * progress.clamp(0., 1.)))
        });
    let backdrop = div()
        .id(SharedString::from(format!("{name}-backdrop")))
        .absolute()
        .inset_0()
        // Nothing beneath takes the mouse while the panel is open.
        .occlude()
        .on_click(close)
        .child(dim)
        .child(panel);
    // Lets UI tests find the panel and backdrop; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(backdrop).into_any_element()
}

/// A panel closing: `content` going the way it came, with the dimming fading
/// out, taking neither the mouse nor focus. `closed` counts the times a panel
/// has closed, so each closing animates afresh.
pub fn closing_panel(content: AnyView, closed: usize, cx: &App) -> AnyElement {
    let theme = cx.theme();
    let panel = div()
        .absolute()
        .left(INSET)
        .right(INSET)
        .top(INSET)
        .bottom(INSET)
        .overflow_hidden()
        .rounded_lg()
        .border_1()
        .border_color(theme.border)
        .bg(theme.background)
        .shadow_2xl()
        .child(div().size_full().child(content))
        .with_spring(("inset-panel-out", closed), motion(false), |panel, progress| {
            frame(progress, panel)
        });
    let dim = div()
        .absolute()
        .inset_0()
        .with_spring(("inset-panel-dim-out", closed), motion(false), |dim, progress| {
            dim.bg(black().opacity(DIM * progress.clamp(0., 1.)))
        });
    div()
        .absolute()
        .inset_0()
        .child(dim)
        .child(panel)
        .into_any_element()
}
